import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Template-based query construction for different report types
        Map<String, String> templateVars = new HashMap<>();
        templateVars.put("table", getTableForReport(reportType));
        templateVars.put("date_filter", buildDateFilter(dateRange));
        templateVars.put("user_filter", userId != null ? "AND user_id = '" + userId + "'" : "");
        templateVars.put("order", sortCol != null ? sortCol : "created_at DESC");

        String queryTemplate = "SELECT id, title, amount, created_at FROM ${table} " +
                "WHERE 1=1 ${date_filter} ${user_filter} " +
                "ORDER BY ${order} LIMIT 500";

        StringSubstitutor sub = new StringSubstitutor(templateVars);
        String finalQuery = sub.replace(queryTemplate);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"amount\": %.2f, \"date\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    private String getTableForReport(String type) {
        switch (type) {
            case "expenses": return "expense_reports";
            case "invoices": return "invoice_records";
            case "payments": return "payment_history";
            default: return "expense_reports";
        }
    }

    private String buildDateFilter(String range) {
        // range format: "2024-01-01,2024-12-31"
        String[] parts = range.split(",");
        if (parts.length == 2) {
            return "AND created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "'";
        }
        return "";
    }
}
